function qpos_h($value): string
{
    return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
}

function qpos_atomic_write(string $destination, string $contents, ?int $mode = null): void
{
    $directory = dirname($destination);
    $temporary = tempnam($directory, '.qpos-costcode-v4-');
    if ($temporary === false) {
        throw new RuntimeException('Could not create a temporary file in '.$directory);
    }

    try {
        $bytes = file_put_contents($temporary, $contents, LOCK_EX);
        if ($bytes === false || $bytes !== strlen($contents)) {
            throw new RuntimeException('Could not completely write '.$destination);
        }
        if ($mode !== null) {
            @chmod($temporary, $mode & 0777);
        }
        if (! @rename($temporary, $destination)) {
            throw new RuntimeException('Could not atomically replace '.$destination);
        }
    } finally {
        if (is_file($temporary)) {
            @unlink($temporary);
        }
    }
}

function qpos_clear_files(string $directory, callable $shouldDelete, array &$messages): int
{
    if (! is_dir($directory)) {
        return 0;
    }

    $count = 0;
    try {
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::CHILD_FIRST
        );
        foreach ($iterator as $item) {
            if ($item->isFile() && $shouldDelete($item->getPathname(), $item->getFilename())) {
                if (@unlink($item->getPathname())) {
                    $count++;
                } else {
                    $messages[] = 'Could not clear cached file: '.$item->getPathname();
                }
            }
        }
    } catch (Throwable $exception) {
        $messages[] = 'Cache cleanup notice: '.$exception->getMessage();
    }

    return $count;
}

